parameters.jsCode:
const text = $json.output[0].content[0].text;

try {
  const data = JSON.parse(text);

  return [
    {
      json: {
        parse_ok: true,
        ...data
      }
    }
  ];
} catch (error) {
  return [
    {
      json: {
        parse_ok: false,
        error: "La respuesta de OpenAI no contiene JSON válido",
        raw_response: text
      }
    }
  ];
}

const productos = items.map(item => {
  const f = item.json.fields;

  return {
    id: item.json.id,
    nombre: f.Nombre,
    categoria: f["Categoría"],
    descripcion: f["Descripción"],
    precio: f.Precio,
    stock: f.Stock
  };
});

return [
  {
    json: {
      productos
    }
  }
];

